  "implementation": "def solve(case):
    nodes = case["nodes"]
    core_dist = case["core_distance"]
    distances = case["distances"]
    n = len(nodes)
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        w = max(core_dist[u], core_dist[v], d)
        edges.append((u, v, w))
    edges.sort(key=lambda e: (e[2], e[0], e[1]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for u, v, w in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    return {"mst_edges": mst_edges, "total_weight": total_weight}
